const number = (r: { numerator: number; denominator: number }) => r.numerator / r.denominator;
const linear = (progress: number) => progress;

function project(snapshot: ReturnType<ReturnType<typeof createFlow>["getSnapshot"]>) {
  return {
    selected: snapshot.phase,
    transition: snapshot.isTransitioning
      ? { kind: "active", direction: snapshot.direction, progress: snapshot.progress }
      : { kind: "inactive" },
    cooldown_active: snapshot.isCoolingDown,
    locked: snapshot.isLocked,
  };
}

describe("shared O01-O10 semantic traces", () => {
  for (const trace of traces) test(`${trace.id} [${trace.covers.join(",")}]`, () => {
    const flow = createFlow({ phases: [...trace.phases], initialPhase: trace.initial, transition: { duration: number(trace.transition_duration), easing: linear }, cooldown: number(trace.cooldown) });
    for (const action of trace.actions) {
      let disposition: boolean | undefined;
      switch (action.kind) {
        case "next": disposition = flow.next(); break;
        case "previous": disposition = flow.previous(); break;
        case "known-target": disposition = flow.navigate(action.target); break;
        case "lock": flow.lock(); break;
        case "unlock": flow.unlock(); break;
        case "tick": flow.tick(number(action.dt)); break;
      }
      if ("disposition" in action) expect(disposition).toBe(action.disposition === "accepted");
      const actual = project(flow.getSnapshot());
      expect(actual.selected).toBe(action.expected.selected);
      expect(actual.cooldown_active).toBe(action.expected.cooldown_active);
      expect(actual.locked).toBe(action.expected.locked);
      expect(actual.transition.kind).toBe(action.expected.transition.kind);
      if (action.expected.transition.kind === "active") {
        if (actual.transition.kind !== "active") throw new Error("expected active transition");
        expect(actual.transition.direction).toBe(action.expected.transition.direction);
        expect(actual.transition.progress).toBe(number(action.expected.transition.progress));
      }
    }
  });
});
